const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7'); // You must include this line

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2018-01-01';
    const end = '2019-01-01';
    const dcFeat = ee.FeatureCollection('TIGER/2018/Counties')
      .filter(ee.Filter.eq('NAME', 'District of Columbia'))
      .first();
    const dcGeom = ee.Feature(dcFeat).geometry().buffer(0);

    // Helper to getInfo as Promise
    const getInfo = (obj) =>
      new Promise((resolve, reject) => {
        obj.getInfo((res, err) => {
          if (err) reject(err);
          else resolve(res);
        });
      });

    // 2. Data Acquisition & Check with fallback
    let dataset = 'PRISM';
    let bandName = 'ppt';
    let scale = 4000;

    let col = ee.ImageCollection('OREGONSTATE/PRISM/AN81m')
      .filterDate(start, end)
      .select(['ppt']);

    let size = await getInfo(col.size());
    console.log(`Primary Dataset: PRISM monthly ppt`);
    console.log(`2018 Images (PRISM): ${size}`);

    if (!size || size === 0) {
      // Fallback to CHIRPS daily
      dataset = 'CHIRPS';
      bandName = 'precipitation';
      scale = 5000;
      col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
        .filterDate(start, end)
        .select([bandName]);
      size = await getInfo(col.size());
      console.log(`Fallback Dataset: CHIRPS daily`);
      console.log(`2018 Images (CHIRPS): ${size}`);
      if (!size || size === 0) {
        console.log('No images available for 2018 in both datasets.');
        console.log('C1');
        return;
      }
    }

    // 3. Processing: Sum precipitation over the year
    const annualSum = col.sum().rename(bandName); // mm over 2018

    // Valid pixel count
    const pixCountDict = await getInfo(
      annualSum.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: dcGeom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true,
      })
    );
    const validPixels = pixCountDict ? pixCountDict[bandName] : null;
    console.log(`Valid Pixels: ${validPixels}`);

    if (!validPixels || validPixels === 0) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }

    // 4. Calculation: Area-mean annual precipitation in mm
    const meanDict = await getInfo(
      annualSum.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: dcGeom,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true,
      })
    );
    const annualMm = meanDict ? meanDict[bandName] : null;

    if (annualMm === null || annualMm === undefined || isNaN(annualMm) || annualMm < 0 || annualMm > 10000) {
      console.log(`Annual precip mm invalid: ${annualMm}`);
      console.log('C3');
      return;
    }

    const annualIn = annualMm / 25.4;

    // 5. Validation & Final Answer
    console.log(`Dataset Used: ${dataset}`);
    console.log(`Annual Precip (mm): ${annualMm.toFixed(1)}`);
    console.log(`Annual Precip (in): ${annualIn.toFixed(2)}`);
    console.log(`Threshold (in): 50.00`);

    if (annualIn >= 50) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
